def early_deletion_days(min_days, days_stored):
    return max(0, min_days - days_stored)

tiers_min_days = {"hot": 0, "cool": 30, "cold": 90, "archive": 180}

scenarios = [
    ("cool", 21),
    ("cold", 40),
    ("archive", 45),
]

for tier, days_stored in scenarios:
    penalty = early_deletion_days(tiers_min_days[tier], days_stored)
    print(f"{tier}: almacenado {days_stored} dias, penalizacion equivalente a {penalty} dias")
